import os
import time

from moler.exceptions import MolerException
from moler.helpers import call_base_class_method_with_same_name, mark_to_call_base_class_method_with_same_name

from ta_moler.device.nokia_unix_remote import NokiaUnixRemote


@call_base_class_method_with_same_name
class PositionerEC(NokiaUnixRemote):
    r"""
    Create Positioner EC device class.

    Example of device in yaml configuration file:
    - with PROXY_PC:
      POSITIONER_PROXY_PC:
        DEVICE_CLASS: ta_moler.device.positioner_ec.PositionerEC
        INITIAL_STATE: UNIX_LOCAL
        CONNECTION_HOPS:
          UNIX_LOCAL:
            PROXY_PC:
              execute_command: ssh
              command_params:
                expected_prompt: "proxy_pc#"
                host: proxy_pc_host
                login: proxy_pc_login
                password: password
                set_timeout: null
          PROXY_PC:
            UNIX_REMOTE:
              execute_command: ssh
              command_params:
                host: windows.nsn-rdnet.net
                login: user-lab0
                password: password15002900
                expected_prompt: user-lab0@PLKR.*:(?!(~/positioner))
                set_timeout: null
          UNIX_REMOTE:
            POSITIONER:
              execute_command: cd
              command_params:
                path:  ~/positioner
                expected_prompt: "user-lab0@PLKR.*:~/positioner$"
            PROXY_PC:
              command_params:
                expected_prompt: "proxy_pc#"

    -without PROXY_PC:
      POSITIONER:
        DEVICE_CLASS: ta_moler.device.positioner_ec.PositionerEC
        INITIAL_STATE: UNIX_LOCAL
        CONNECTION_HOPS:
          UNIX_LOCAL:
            UNIX_REMOTE:
              execute_command: ssh
              command_params:
                host: windows.nsn-rdnet.net
                login: user-lab0
                password: password15002900
                expected_prompt: user-lab0@PLKR.*:(?!(~/positioner))
                set_timeout: null
          UNIX_REMOTE:
            POSITIONER:
              execute_command: cd
              command_params:
                path:  ~/positioner
                expected_prompt: "user-lab0@PLKR.*:~/positioner$"
    """

    positioner = "POSITIONER"

    def __init__(
        self,
        sm_params,
        name=None,
        io_connection=None,
        io_type=None,
        variant=None,
        io_constructor_kwargs=None,
        initial_state=None,
        lazy_cmds_events=False,
    ):
        """
        Create Positioner EC device communicating over io_connection.

        :param sm_params: dict with parameters of state machine for device
        :param name: name of device
        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: type of connection - tcp, udp, ssh, telnet, ...
        :param variant: connection implementation variant, ex. 'threaded', 'twisted', 'asyncio', ...
                        (if not given then default one is taken)
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: name of initial state. State machine tries to enter this state just after creation.
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        """
        initial_state = initial_state if initial_state is not None else PositionerEC.positioner
        super(PositionerEC, self).__init__(
            name=name,
            io_connection=io_connection,
            io_type=io_type,
            variant=variant,
            io_constructor_kwargs=io_constructor_kwargs,
            sm_params=sm_params,
            initial_state=initial_state,
            lazy_cmds_events=lazy_cmds_events,
        )
        self._positioner_http_ip = "192.168.150.69"
        self._positioner_http_port = 3000
        self._sent_script = False

    @property
    def positioner_http_ip(self):
        """Get current address (IP or domain) of positioner."""
        return self._positioner_http_ip

    @positioner_http_ip.setter
    def positioner_http_ip(self, positioner_http_ip):
        """Set current address (IP or domain) of positioner."""
        self._positioner_http_ip = positioner_http_ip

    @property
    def positioner_http_port(self):
        """Get current http port of positioner."""
        return self._positioner_http_port

    @positioner_http_port.setter
    def positioner_http_port(self, positioner_http_port):
        """Set current http port of positioner."""
        self._positioner_http_port = positioner_http_port

    def _get_positioner_ec_default_sm_configuration(self):
        config = {
            PositionerEC.connection_hops: {
                PositionerEC.unix_remote: {  # from
                    PositionerEC.positioner: {  # to
                        "execute_command": "cd",  # using command
                        "command_params": {  # with parameters
                            "path": "~/positioner/",
                            "expected_prompt": r"user-lab0@PLKR.*:~/positioner\$",
                        },
                        "required_command_params": [],
                    }
                },
                PositionerEC.positioner: {  # from
                    PositionerEC.unix_remote: {  # to
                        "execute_command": "cd",  # using commands
                        "command_params": {  # with parameters
                            "path": r"~",
                            "expected_prompt": r"user-lab0@PLKR.*:(?!(~/positioner))",
                        },
                    },
                },
            }
        }
        return config

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_with_proxy_pc(self):
        """
        Return State Machine default configuration with proxy_pc state.

        :return: default sm configuration with proxy_pc state.
        """
        return self._get_positioner_ec_default_sm_configuration()

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_without_proxy_pc(self):
        """
        Return State Machine default configuration without proxy_pc state.

        :return: default sm configuration without proxy_pc state.
        """
        return self._get_positioner_ec_default_sm_configuration()

    def _prepare_transitions(self):
        super(PositionerEC, self)._prepare_transitions()
        transitions = {
            PositionerEC.positioner: {
                PositionerEC.unix_remote: {
                    "action": ["_execute_command_to_change_state"],
                }
            },
            PositionerEC.unix_remote: {
                PositionerEC.positioner: {
                    "action": ["_execute_positioner_state_cmds"],
                }
            },
        }
        self._add_transitions(transitions=transitions)

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        state_hops = {
            PositionerEC.not_connected: {
                PositionerEC.positioner: PositionerEC.unix_local,
            },
            PositionerEC.unix_local: {
                PositionerEC.positioner: PositionerEC.proxy_pc,
            },
            PositionerEC.unix_local_root: {
                PositionerEC.positioner: PositionerEC.unix_local,
            },
            PositionerEC.proxy_pc: {
                PositionerEC.positioner: PositionerEC.unix_remote,
            },
            PositionerEC.positioner: {
                PositionerEC.unix_local: PositionerEC.unix_remote,
                PositionerEC.unix_local_root: PositionerEC.unix_remote,
                PositionerEC.not_connected: PositionerEC.unix_remote,
                PositionerEC.proxy_pc: PositionerEC.unix_remote,
                PositionerEC.unix_remote_root: PositionerEC.unix_remote,
            },
            PositionerEC.unix_remote_root: {PositionerEC.positioner: PositionerEC.unix_remote, PositionerEC.proxy_pc: PositionerEC.unix_remote},
        }

        return state_hops

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_without_proxy_pc(self):
        state_hops = {
            PositionerEC.not_connected: {
                PositionerEC.positioner: PositionerEC.unix_local,
            },
            PositionerEC.unix_local: {
                PositionerEC.positioner: PositionerEC.unix_remote,
            },
            PositionerEC.unix_local_root: {
                PositionerEC.positioner: PositionerEC.unix_local,
            },
            PositionerEC.positioner: {
                PositionerEC.unix_local: PositionerEC.unix_remote,
                PositionerEC.unix_local_root: PositionerEC.unix_remote,
                PositionerEC.not_connected: PositionerEC.unix_remote,
                PositionerEC.unix_remote_root: PositionerEC.unix_remote,
            },
            PositionerEC.unix_remote_root: {
                PositionerEC.positioner: PositionerEC.unix_remote,
            },
        }
        return state_hops

    def _prepare_positioner_krk_state_prompts(self):
        state_prompts = {
            PositionerEC.positioner: self._configurations[PositionerEC.connection_hops][PositionerEC.unix_remote][PositionerEC.positioner][
                "command_params"
            ]["expected_prompt"],
        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_with_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine with proxy_pc state.

        :return: textual prompt for each state with proxy_pc state.
        """
        return self._prepare_positioner_krk_state_prompts()

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_without_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine without proxy_pc state.

        :return: textual prompt for each state without proxy_pc state.
        """
        return self._prepare_positioner_krk_state_prompts()

    def _get_packages_for_state(self, state, observer):
        available = super(PositionerEC, self)._get_packages_for_state(state, observer)

        if not available:
            if state == PositionerEC.positioner:
                available = {
                    PositionerEC.cmds: ["moler.cmd.unix", "ta_moler.cmd.shared.nokiaunix", "ta_moler.cmd.positioner_ec"],
                    PositionerEC.events: ["moler.events.shared", "moler.events.unix"],
                }
            if available:
                return available[observer]

        return available

    # pylint: disable-next=unused-argument
    def _execute_positioner_state_cmds(self, source_state, dest_state, timeout=-1):
        configurations = self.get_configurations(source_state=source_state, dest_state=dest_state)

        command_name = configurations["execute_command"]
        command_params = configurations["command_params"]
        if self._sent_script is False and command_name == "cd":
            cmd_mkdir = self.get_cmd(cmd_name="mkdir", cmd_params={"path": command_params["path"], "options": "-p"})
            try:
                cmd_mkdir()
            except MolerException:
                pass
        cmd = self.get_cmd(cmd_name=command_name, cmd_params=command_params)  # cd cmd
        cmd()
        if self._sent_script is False:
            script_name = "send_request.py"
            current_dir = os.path.dirname(os.path.abspath(__file__))
            dir_to_file = os.path.abspath(f"{current_dir}/../util/{script_name}")
            with open(dir_to_file) as f:
                content = f.read()
            cmd_tee = self.get_cmd(cmd_name="tee", cmd_params={"path": script_name, "content": content})
            try:
                cmd_tee()
                self._sent_script = True
            except MolerException:
                pass
            time.sleep(0.5)

    def goto_state(
        self, state, timeout=-1, rerun=0, send_enter_after_changed_state=False, log_stacktrace_on_fail=True, keep_state=True, timeout_multiply=1.0,
        sleep_after_changed_state=0.5
    ):
        """
        Go to specific state.

        :param state: Name to state to change on the device.
        :param timeout: Timeout for changing state, if negative then timeout from commands are taken.
        :param rerun: How many times rerun the procedure before it fails.
        :param send_enter_after_changed_state: If True then enter is sent after state is changed. False nothing is sent.
        :param log_stacktrace_on_fail: Set True to have stacktrace in logs when failed, otherwise False.
        :param keep_state: if True and state is changed without goto_state then device tries to change state to state
        defined by goto_state.
        :param timeout_multiply: how many times multiply passed timeout to get final timeout.
        :return: None
        :raise: DeviceChangeStateFailure if cannot change the state of device.
        """
        return super(PositionerEC, self).goto_state(
            state=state,
            timeout=timeout,
            rerun=rerun,
            send_enter_after_changed_state=send_enter_after_changed_state,
            log_stacktrace_on_fail=log_stacktrace_on_fail,
            keep_state=keep_state,
            timeout_multiply=timeout_multiply,
            sleep_after_changed_state=sleep_after_changed_state
        )
